// Thus, the solution is simply to compute that value. Edge cases: If s > k, the formula might produce a negative min; so we enforce 1 ≤ s ≤ k ≤ n, else return -1. If n < k, impossible. Time O(1), space O(1).
#include <algorithm>

// Return the minimum total presses needed under the described elevator rules.
// Constraints: 1 <= s <= k <= n. Returns -1 if constraints are violated.
int minimumPresses(int n, int k, int s) {
    if (n < 1 || k < 1 || s < 1) return -1;
    if (k > n || s > k) return -1;
    
    // Cost breakdown: press button k costs k, free ride k->n, walk n->s costs n-s,
    // return from s to 1 costs min(s, k-s) (either walk down or walk up to k then free down).
    return k + (n - s) + std::min(s, k - s);
}
#include <cassert>

int minimumPresses(int, int, int); // declare

int main() {
    // (n, k, s) -> expected
    assert(minimumPresses(10, 5, 3) == 5 + (10-3) + std::min(3, 5-3) == 5+7+2 == 14);
    assert(minimumPresses(10, 5, 2) == 5 + 8 + std::min(2,3) == 5+8+2 == 15);
    assert(minimumPresses(10, 7, 7) == 7 + 3 + std::min(7,0) == 7+3+0 == 10);
    assert(minimumPresses(5, 4, 1) == 4 + (5-1) + std::min(1,3) == 4+4+1 == 9);
    assert(minimumPresses(3, 2, 1) == 2 + (3-1) + std::min(1,1) == 2+2+1 == 5);
    assert(minimumPresses(1, 1, 1) == 1 + (1-1) + std::min(1,0) == 1+0+0 == 1);
    assert(minimumPresses(10, 3, 5) == -1); // s > k
    assert(minimumPresses(2, 3, 1) == -1); // k > n
    assert(minimumPresses(0, 1, 1) == -1); // n < 1
    assert(minimumPresses(100, 50, 25) == 50 + (100-25) + std::min(25,25) == 50+75+25 == 150);
}
